GameOverviewPage:
query GameOverviewPage($gameId: ID!) {
  game(id: $gameId) {
    id
    org {
      gaId
      __typename
    }
    statsVisible
    gameVideoStatus
    ...GameOverviewPageHeaderFragment
    ...GameOverviewReelsFragment
    ...BoxScoreFragment
    ...GameOverviewAiStatsFragment
    __typename
  }
}

fragment GameOverviewPageHeaderFragment on Game {
  videoDownloadUrl
  videoProcessing
  videoArchived
  gameVideoStatus
  videoAvailableUntil
  playedAt
  videoHlsUrl
  homeScore
  home {
    id
    name
    __typename
  }
  awayScore
  away {
    id
    name
    __typename
  }
  league {
    id
    name
    __typename
  }
  org {
    id
    timeZoneName
    __typename
  }
  thumbnailUrl
  statsVisible
  ...GamePlayerSelectorFragment
  ...GameOverviewAiStatsFragment
  __typename
}

fragment GamePlayerSelectorFragment on Game {
  id
  home {
    id
    name
    __typename
  }
  away {
    id
    name
    __typename
  }
  gamePlayers {
    id
    isHomeTeamPlayer
    ...GamePlayerAvatarFragment
    person {
      id
      fullNameWithAnonymisation
      __typename
    }
    team {
      id
      __typename
    }
    __typename
  }
  __typename
}

fragment GamePlayerAvatarFragment on GamePlayer {
  id
  playerNumber
  isHomeTeamPlayer
  __typename
}

fragment GameOverviewAiStatsFragment on Game {
  id
  aiStatsAvailable
  aiStatsStatus
  aiStatsRequestedByCurrentUser
  __typename
}

fragment GameOverviewReelsFragment on Game {
  id
  home {
    id
    __typename
  }
  away {
    id
    __typename
  }
  __typename
}

fragment BoxScoreFragment on Game {
  participations {
    id
    team {
      id
      name
      __typename
    }
    __typename
  }
  __typename
}

BoxScore:
query BoxScore($gameId: ID!) {
  game(id: $gameId) {
    id
    participations {
      id
      isHomeTeam
      team {
        id
        name
        __typename
      }
      overviewStats {
        shortName
        name
        ...StatValueFragment
        __typename
      }
      gamePlayers {
        id
        playerNumber
        person {
          id
          fullNameWithAnonymisation
          __typename
        }
        boxScoreStats {
          shortName
          name
          ...StatsTableStatCellFragment
          __typename
        }
        __typename
      }
      boxScoreTotalStats {
        shortName
        name
        ...StatsTableStatCellFragment
        __typename
      }
      __typename
    }
    __typename
  }
}

fragment StatValueFragment on Stat {
  statType
  value
  made
  total
  __typename
}

fragment StatsTableStatCellFragment on Stat {
  statType
  value
  made
  total
  __typename
}

PointChart:
query PointChart($gameId: ID!) {
  game(id: $gameId) {
    id
    home {
      id
      name
      __typename
    }
    away {
      id
      name
      __typename
    }
    pointChart {
      maxScore
      entries {
        timeString
        homeScore
        awayScore
        __typename
      }
      periods {
        name
        startTimeString
        finishTimeString
        __typename
      }
      __typename
    }
    __typename
  }
}

ShotChart:
query ShotChart($gameId: ID!) {
  game(id: $gameId) {
    id
    periodType
    participations {
      id
      isHomeTeam
      team {
        id
        name
        __typename
      }
      gamePlayers {
        id
        playerNumber
        person {
          id
          fullNameWithAnonymisation
          __typename
        }
        events(hasCoordinates: true) {
          id
          made
          createdByPerson {
            id
            __typename
          }
          period {
            name
            number
            __typename
          }
          coordinates {
            x
            y
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
